// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MigrationAttempt) predicate.MigrationAttempt {
	return predicate.MigrationAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MigrationAttempt) predicate.MigrationAttempt {
	return predicate.MigrationAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MigrationAttempt) predicate.MigrationAttempt {
	return predicate.MigrationAttempt(sql.NotPredicates(p))
}
